const $=s=>document.querySelector(s),alive=()=>$('#writing-form')!==null&&!disposed;const processToggle=$('.writing-process-toggle');if(processToggle){let open=true;try{open=localStorage.getItem('paperknow-writing-process')!=='hidden';}catch{}const apply=()=>{document.querySelector('.writing-process-guide')?.classList.toggle('is-collapsed',!open);processToggle.setAttribute('aria-expanded',String(open));processToggle.textContent=open?'隐藏流程':'显示流程';};apply();processToggle.addEventListener('click',()=>{open=!open;apply();try{localStorage.setItem('paperknow-writing-process',open?'visible':'hidden');}catch{}});}
