const normalizeReference=row=>({id:String(row?.id||referenceId()),title:String(row?.title||row?.name||'未命名文献').trim(),authors:String(row?.authors||row?.author||'作者待补充').trim(),year:String(row?.year||'年份待补充'),doi:String(row?.doi||''),url:String(row?.url||''),tags:Array.isArray(row?.tags)?row.tags:[],scope:String(row?.scope||'本地文献库'),text:String(row?.text||''),fileName:String(row?.fileName||''),source:row?.source||'local'});
