function referenceCandidates(){const papers=literatureRows().map(normalizeReference);const selected=writingReferences.map(normalizeReference);const seen=new Set();return [...papers,...selected].filter(row=>{const key=referenceKey(row);if(seen.has(key))return false;seen.add(key);return true;});}
function renderWritingReferences(){const list=$('#writing-reference-list');if(!list)return;const query=($('#writing-reference-query')?.value||'').trim().toLowerCase();let rows=referenceCandidates();if(referenceMode==='search'&&query)rows=rows.filter(row=>[row.title,row.authors,row.doi,row.scope,...row.tags].join(' ').toLowerCase().includes(query));if(referenceMode==='recommend')rows=rows.slice(0,6);if(referenceMode==='search'&&!query)rows=[];const selected=new Set(writingReferences.map(referenceKey));$('#writing-reference-count').textContent=`已选 ${writingReferences.length} 篇`;if(!rows.length){list.innerHTML=`<div class="reference-empty"><span class="reference-empty-icon">⌕</span><div><b>${referenceMode==='search'?'输入关键词开始搜索':'文献库暂无可展示内容'}</b><p>${referenceMode==='search'?'可搜索当前浏览器中已保存的题目、作者、DOI 或关键词。':'先导入文献，或前往文献库保存资料后再回来确认。'}</p></div></div>`;return;}list.innerHTML=`<div class="reference-list-head"><div><b>${referenceMode==='recommend'?'本地推荐文献':referenceMode==='search'?'搜索结果':'已导入文献'}</b><small>${referenceMode==='recommend'?'根据当前文献库展示，选择后才会用于本次写作。':`${rows.length} 条结果`}</small></div><span>${writingReferences.length} 篇已选</span></div><div class="reference-list-items">${rows.map(row=>{const checked=selected.has(referenceKey(row));return `<article class="reference-row ${checked?'is-selected':''}"><button type="button" class="reference-row-toggle" data-reference-id="${esc(row.id)}" aria-pressed="${checked}"><span class="reference-check">${checked?'✓':''}</span><span><b>${esc(row.title)}</b><small>${esc(row.authors)} · ${esc(row.year)}${row.doi?` · DOI ${esc(row.doi)}`:''}</small><em>${esc(row.scope||'本地文献库')}${row.fileName?` · ${esc(row.fileName)}`:''}</em></span></button><span class="reference-row-status">${checked?'已选':'选择'}</span></article>`;}).join('')}</div>`;}
function setReferenceMode(mode){referenceMode=mode;document.querySelectorAll('[data-reference-mode]').forEach(card=>card.classList.toggle('is-active',card.dataset.referenceMode===mode));const panel=$('#writing-reference-search-panel');if(panel)panel.hidden=mode!=='search';if(mode==='import'){$('#writing-reference-file')?.click();return;}renderWritingReferences();}
function toggleReference(id){const row=referenceCandidates().find(item=>String(item.id)===String(id));if(!row)return;const index=writingReferences.findIndex(item=>referenceKey(item)===referenceKey(row));if(index>=0)writingReferences.splice(index,1);else writingReferences.push({...normalizeReference(row),source:row.source||'local'});renderWritingReferences();}
async function importWritingReferences(file){if(!file)return;if(file.size>50*1024*1024){$('#writing-reference-status').textContent='请选择不超过 50MB 的文件。';return;}$('#writing-reference-status').textContent='正在解析文献…';try{let rows=[];if(/\.json$/i.test(file.name)){const data=JSON.parse(await file.text());rows=Array.isArray(data)?data:(Array.isArray(data?.papers)?data.papers:[]);if(!rows.length)throw new Error('JSON 中没有可导入的文献记录。');}else{if(!/\.(docx|pdf|txt)$/i.test(file.name))throw new Error('支持 JSON、DOCX、PDF 或 TXT。');const {extractFile}=await import('/precheck/assets/parsers.js');const parsed=await extractFile(file);if(!parsed.text.trim())throw new Error('未提取到文献正文，请检查文件。');rows=[{title:file.name.replace(/\.[^.]+$/,''),authors:'作者待补充',year:new Date().getFullYear(),scope:'导入文献',fileName:file.name,text:parsed.text,source:'import'}];}let added=0;for(const raw of rows){const row=normalizeReference({...raw,source:'import',fileName:raw.fileName||file.name});if(writingReferences.some(item=>referenceKey(item)===referenceKey(row)))continue;writingReferences.push(row);added++;}referenceMode='import';document.querySelectorAll('[data-reference-mode]').forEach(card=>card.classList.toggle('is-active',card.dataset.referenceMode==='import'));$('#writing-reference-status').textContent=`已导入 ${added} 篇文献，请确认需要用于本次论文的文献。`;renderWritingReferences();}catch(err){$('#writing-reference-status').textContent=err.message||'文献导入失败，请检查文件。';}finally{$('#writing-reference-file').value='';}}
const values=()=>({projectId:$('#writing-project').value,title:$('#writing-title').value.trim(),degree:$('#writing-degree').value,major:$('#writing-major').value.trim(),language:$('#writing-language').value,mode:'毕业论文',targetWords:$('#writing-target').value,formula:$('#writing-formula').value,materialPurpose:$('#material-purpose').value});
