const outlineRowId=()=>`outline-row-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const isOutlineRowLine=line=>{const value=String(line||'').trim();return /^第[^\s]{1,16}章/.test(value)||/^参考文献/.test(value)||/^摘要$|^Abstract$/i.test(value)||/^\d+(?:\.\d+)+(?:\s+|[、.：:]|$)/.test(value);};
function parseOutlineRows(text){const lines=String(text||'').replace(/\r\n?/g,'\n').split('\n');const target=Number($('#writing-target')?.value||0);const candidates=[];for(let i=0;i<lines.length;i++){const raw=lines[i],value=raw.trim();if((i<2&&!isOutlineRowLine(value))||!value||/^(写作语言|目标字数|研究方法|研究要求|本地结构模板)/.test(value))continue;if(!isOutlineRowLine(raw))continue;const chapter=/^第[^\s]{1,16}章|^参考文献|^摘要$|^Abstract$/i.test(value);candidates.push({id:outlineRowId(),title:value,level:chapter?1:2,words:0});}if(!candidates.length)return outlineChapters.map(line=>({id:outlineRowId(),title:String(line).trim(),level:String(line).startsWith('　')?2:1,words:0}));const average=target?Math.max(100,Math.round(target/candidates.length/10)*10):0;return candidates.map(row=>({...row,words:average}));}
function ensureOutlineRows(){if(!outlineRowsReady){outlineRows=parseOutlineRows(content);outlineRowsReady=true;}}
