function syncOutlineRowsToContent(){ensureOutlineRows();const lines=String(content||'').replace(/\r\n?/g,'\n').split('\n'),firstOutlineIndex=lines.findIndex(line=>isOutlineRowLine(String(line||'').trim()));const head=lines.slice(0,firstOutlineIndex<0?2:firstOutlineIndex).filter(Boolean);const tail=lines.filter(line=>/^(写作语言|目标字数|研究方法|研究要求|本地结构模板)/.test(String(line||'').trim()));content=[...head,'',...outlineRows.map(row=>`${row.level===2?'　':''}${String(row.title||'').trim()}`),...tail].filter(Boolean).join('\n');const sourceInput=$('#outline-source-input');if(sourceInput&&document.activeElement!==sourceInput)sourceInput.value=content;outlineState='edited';}
function outlineRowMarkup(row,index){const words=Number(row.words)||0;return `<div class="outline-edit-row ${row.level===1?'is-chapter':'is-subsection'}" data-outline-row-id="${esc(row.id)}"><span class="outline-row-level">${row.level===1?'章':'节'}</span><div class="outline-row-fields"><input class="outline-row-title" data-outline-field="title" value="${esc(row.title)}" aria-label="提纲${row.level===1?'章节':'小节'}标题"><div class="outline-row-controls"><label>目标字数 <input class="outline-row-words" data-outline-field="words" type="number" min="0" max="100000" step="10" value="${words||''}" placeholder="未设置"></label><span class="outline-row-count">${words?`${words.toLocaleString('zh-CN')} 字`:'未设置'}</span></div></div><div class="outline-row-actions"><button type="button" data-outline-action="up" ${index===0?'disabled':''} aria-label="上移">↑</button><button type="button" data-outline-action="down" ${index===outlineRows.length-1?'disabled':''} aria-label="下移">↓</button><button type="button" data-outline-action="remove" aria-label="删除">×</button></div></div>`;}
function renderOutlineEditor(){const paper=$('#outline-paper');if(!paper||workflowStage!==4||outlineConfirmed)return;ensureOutlineRows();const total=outlineTotalWords(),target=Number($('#writing-target')?.value||0),warning=target&&total>target?`已超过目标字数 ${target.toLocaleString('zh-CN')} 字，请调整章节分配。`:target?`还可分配 ${(target-total).toLocaleString('zh-CN')} 字`:'可以为每章设置目标字数';paper.innerHTML=`<div class="outline-editing-shell"><div class="outline-editing-head"><div><b>提纲内容与字数分配</b><small>修改章节标题、层级和目标字数，确认后才会进入正文写作。</small></div><span class="outline-total-words ${target&&total>target?'is-over':''}">合计 ${total.toLocaleString('zh-CN')} 字${target?` / 目标 ${target.toLocaleString('zh-CN')} 字`:''}</span></div><div class="outline-editing-note">${esc(warning)}</div><div class="outline-editing-rows">${outlineRows.map(outlineRowMarkup).join('')}</div><div class="outline-editing-add"><button type="button" class="btn secondary" data-outline-add="chapter">＋ 新增章节</button><button type="button" class="btn secondary" data-outline-add="subsection">＋ 新增小节</button></div></div>`;}
function refreshOutlineTotals(){const total=outlineTotalWords(),target=Number($('#writing-target')?.value||0),totalNode=$('#outline-paper .outline-total-words'),note=$('#outline-paper .outline-editing-note');if(totalNode){totalNode.classList.toggle('is-over',!!(target&&total>target));totalNode.textContent=`合计 ${total.toLocaleString('zh-CN')} 字${target?` / 目标 ${target.toLocaleString('zh-CN')} 字`:''}`;}if(note)note.textContent=target&&total>target?`已超过目标字数 ${target.toLocaleString('zh-CN')} 字，请调整章节分配。`:target?`还可分配 ${(target-total).toLocaleString('zh-CN')} 字`:'可以为每章设置目标字数';document.querySelectorAll('#outline-paper .outline-edit-row').forEach(row=>{const id=row.dataset.outlineRowId,item=outlineRows.find(entry=>String(entry.id)===String(id)),count=row.querySelector('.outline-row-count');if(item&&count)count.textContent=item.words?`${Number(item.words).toLocaleString('zh-CN')} 字`:'未设置';});}
function updateOutlineRow(id,field,value){ensureOutlineRows();const row=outlineRows.find(item=>String(item.id)===String(id));if(!row)return;if(field==='words')row.words=Math.max(0,Math.min(100000,Number(value)||0));else row.title=String(value||'').trim();syncOutlineRowsToContent();refreshOutlineTotals();$('#writing-status').textContent='提纲已修改，请确认后保存。';}
