function addOutlineRow(level){ensureOutlineRows();outlineRows.push({id:outlineRowId(),title:level===1?'新章节标题':'新小节标题',level,words:0});syncOutlineRowsToContent();renderOutlineEditor();const last=$('#outline-paper .outline-edit-row:last-child .outline-row-title');last?.focus();}
function renderOutlineBuilder(){const input=$('#outline-source-input'),status=$('#outline-builder-status');if(!input||!status)return;if(document.activeElement!==input&&outlineSource&&input.value!==content)input.value=content;status.textContent=outlineSource==='uploaded'?'已导入提纲，可继续编辑后使用。':outlineSource==='pasted'?'已使用粘贴提纲，可继续编辑。':content?'已有本地提纲，可重新生成或替换。':'请选择一种方式创建或替换提纲。';}
