function ensureKnowledgeFiles(){if(!knowledgeFiles.length&&material)knowledgeFiles=[{id:'legacy-material',name:fileName||'参考材料',purpose:fileName?'资料':'AI 补充',text:material,state:materialState,kind:fileName?'file':'ai'}];return knowledgeFiles;}function syncKnowledgeMaterial(){const items=ensureKnowledgeFiles();material=items.map(f=>f.text||'').filter(Boolean).join('\n\n');const last=items[items.length-1];fileName=last?.kind==='file'?last.name||'':'';materialState=last?.state||'saved';if($('#writing-material'))$('#writing-material').value=material;}function knowledgeId(){return `knowledge-${Date.now()}-${Math.random().toString(16).slice(2)}`;}function renderKnowledgeSummary(){const summary=$('#writing-material-summary');if(!summary)return;const items=ensureKnowledgeFiles();const ai=items.find(item=>item.kind==='ai');if(ai&&$('#knowledge-ai-input')&&!$('#knowledge-ai-input').value)$('#knowledge-ai-input').value=ai.text||'';const count=items.length;if(items.length){summary.innerHTML=`<div class="knowledge-summary-head"><div><b>已添加资料 ${count}/4</b><small>已添加的 AI 说明和上传资料会用于完善后续论文提纲。</small></div><span>${count===1?'1 份资料':`${count} 份资料`}</span></div><div class="knowledge-material-list">${items.map(item=>{const state=item.state==='parsed'?'已解析':item.state==='edited'?'已记录':'已保存';return `<div class="knowledge-material-row"><span class="knowledge-material-type">${item.kind==='ai'?'AI':'文档'}</span><div><b>${esc(item.name||'参考资料')}</b><small>${esc(item.purpose||'其他资料')} · ${(item.text||'').length.toLocaleString('zh-CN')} 字符 · ${state}</small></div><button type="button" data-knowledge-action="remove" data-knowledge-id="${esc(item.id)}">移除</button></div>`;}).join('')}</div>`;}else summary.innerHTML='<div class="knowledge-empty"><div class="knowledge-empty-icon">＋</div><div><b>已添加资料 0/4</b><p>暂无资料，可直接跳过此步</p><small>上传资料仅用于当前论文，支持随时删除。</small></div></div>';const confirm=$('#writing-material-confirm');if(confirm)confirm.textContent=material?'确认补充，进入参考文献确认 →':'继续，进入参考文献确认 →';}function updateWorkflow(){document.querySelector('.dashboard')?.setAttribute('data-writing-stage',String(workflowStage));document.querySelectorAll('[data-writing-step]').forEach(b=>{const step=Number(b.dataset.writingStep);b.classList.toggle('active',step===workflowStage);b.classList.toggle('is-complete',step<workflowStage);if(step===workflowStage)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current','step');b.disabled=step===3?!content:step===4?!content:step===5?!outlineConfirmed:false;});$('.creation-output')?.classList.toggle('is-stage-hidden',workflowStage===1);$('.creation-input')?.classList.toggle('is-stage-hidden',workflowStage>=2);$('.task-overview')?.toggleAttribute('hidden',workflowStage<5);$('#writing-material-review').hidden=workflowStage!==2;$('#writing-reference-review').hidden=workflowStage!==3;renderKnowledgeSummary();renderWritingReferences();renderOutlineBuilder();$('#writing-outline-area').hidden=workflowStage<4||workflowStage>=5||(workflowStage===4&&outlineConfirmed);$('#writing-body-area').hidden=workflowStage!==4||!outlineConfirmed;$('#writing-export-area').hidden=workflowStage!==5;$('.preview-heading h2').textContent=workflowStage===4&&!outlineConfirmed?'论文提纲确认':workflowStage===4?'分章节写作':workflowStage===5?'编辑与导出':'论文框架预览';$('.preview-heading').hidden=workflowStage===2||workflowStage===3;$('#writing-example-note').hidden=workflowStage===2||workflowStage===3||!!content;const processNames=['基础信息填写','精准知识补充','参考文献确认','论文提纲确认','生成版本确认'];const processText=$('#writing-process-context-text'),processNext=$('#writing-process-next');if(processText)processText.textContent=workflowStage===5?'当前步骤：请检查格式并导出已填写的论文内容。':`当前步骤：${processNames[workflowStage-1]}，完成后再进入下一步。`;if(processNext){processNext.textContent=workflowStage<5?`下一步：${processNames[workflowStage]}　→`:'已完成全部步骤';processNext.disabled=workflowStage>=5;}if(workflowStage===4&&!outlineConfirmed)renderOutlineEditor();}

